$("#modal-class_semester").on("submit",function(event) {

    event.preventDefault();

    let semester_name = $("#semester_id").val();
    let class_name = $("#class_id").val();
    let id = $("#update_id").val();
   

    let sendingData = {}

    if(btnAction == "Insert"){
        sendingData = {
          
            "semester_id" : semester_name,
            "class_id":class_name,
            "action" :  "register_class_semester" 
            
        }
    
    }
    else{
          sendingData = {
            "semester_id" : semester_name,
            "class_id":class_name,
            "class_semester_id" : id,
            "action" : "Update_class_semester"
            
        }
    
    }

    
  
    $.ajax( {
        method: "POST",
        dataType: "JSON",
        url : "../APi/class_semester.php",
        data : sendingData,
        success: function(data){

            let status = data.status;
            let response = data.data;

            if(status){

                Swal.fire({
                    title: response,
                    icon: "success"
                  });

                  setTimeout(() => {
              
                    $(".modal-class_semester").hide();
                  }, 1000);

                console.log("success",response);
                btnAction = "Insert";
                loadData();
            }else{
                alert("error",response);
            }
           

        },
        error: function(data){
          console.log("error",data);
        }
    })

})


loadData();
function loadData(){

    $("#class_semester_Table tbody").html('');

    let sendingData = {
        "action" : "class_semesterment_read"
    }

    $.ajax( {
        method: "POST",
        dataType: "JSON",
        url : "../APi/class_semester.php",
        data : sendingData,
        success: function(data){

            let status = data.status;
            let response = data.data;
            let html = '';
            let tr = '';

            if(status){

                response.forEach( itm => {

                    tr += "<tr>";
                    for(let i in itm){

                      
                            tr += `<td>${itm[i]}</td>`;
                        }

                    

                        tr += `<td > <buttonclass="btn_upda"> <a class="updete_cl"update_id=${itm['class_semester_id']}><span class="material-symbols-outlined" style ="color:#fff;background-color:var(--base-clr); font-size: xx-large;  font-weight: bold; border-radius: 5px; ">edit
                        </span></a></button> &nbsp;&nbsp;<a class="delete_cl" delete_id=${itm['class_semester_id']}><span class="material-symbols-outlined" style ="color:#fff;background-color:red;font-size: xx-large;  font-weight: bold; border-radius: 5px;">delete
                        </span></a> </td>` 
                       
                        tr += '</tr>'  

                })

                $("#class_semester_Table tbody").append(tr);

            }else{
                console.log("error",response);
            }
           

        },
        error: function(data){
            console.log(data);

        }
    })

}



