semester_name();

function semester_name(){

   

    let sendingData = {
        "action" : "semester_read"
    }

    $.ajax( {
        method: "POST",
        dataType: "JSON",
        url : "../APi/semester.php",
        data : sendingData,
        success: function(data){

            let status = data.status;
            let response = data.data;
            let html = '';
            let tr = '';

            if(status){

                
                response.forEach( res => {

                   html += `<option value="${res['semester_id']}">${res['semester_name']}</option>`;
                })

                $("#semester_id").append(html);

              
            }else{
                alert("error",response);
            }
           

        },
        error: function(data){

        }
    })

}



